P4Parser::P4Parser(TokenStream *input) : P4Parser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

P4Parser::P4Parser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  P4Parser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *p4parserParserStaticData->atn, p4parserParserStaticData->decisionToDFA, p4parserParserStaticData->sharedContextCache, options);
}

P4Parser::~P4Parser() {
  delete _interpreter;
}

const atn::ATN& P4Parser::getATN() const {
  return *p4parserParserStaticData->atn;
}

std::string P4Parser::getGrammarFileName() const {
  return "P4Parser.g4";
}

const std::vector<std::string>& P4Parser::getRuleNames() const {
  return p4parserParserStaticData->ruleNames;
}

const dfa::Vocabulary& P4Parser::getVocabulary() const {
  return p4parserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView P4Parser::getSerializedATN() const {
  return p4parserParserStaticData->serializedATN;
}


//----------------- ProgramContext ------------------------------------------------------------------

P4Parser::ProgramContext::ProgramContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* P4Parser::ProgramContext::EOF() {
  return getToken(P4Parser::EOF, 0);
}

std::vector<P4Parser::DeclarationContext *> P4Parser::ProgramContext::declaration() {
  return getRuleContexts<P4Parser::DeclarationContext>();
}

P4Parser::DeclarationContext* P4Parser::ProgramContext::declaration(size_t i) {
  return getRuleContext<P4Parser::DeclarationContext>(i);
}

std::vector<tree::TerminalNode *> P4Parser::ProgramContext::SEMICOLON() {
  return getTokens(P4Parser::SEMICOLON);
}

tree::TerminalNode* P4Parser::ProgramContext::SEMICOLON(size_t i) {
  return getToken(P4Parser::SEMICOLON, i);
}


size_t P4Parser::ProgramContext::getRuleIndex() const {
  return P4Parser::RuleProgram;
}

void P4Parser::ProgramContext::enterRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<P4ParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->enterProgram(this);
}

void P4Parser::ProgramContext::exitRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<P4ParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->exitProgram(this);
}


std::any P4Parser::ProgramContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<P4ParserVisitor*>(visitor))
    return parserVisitor->visitProgram(this);
  else
    return visitor->visitChildren(this);
}

